<template><span ref="host" class="ui-tour-host"><MDialog :id="identity" ref="panel" :model-value="modelValue" class="ui-tour__dialog" :style="styles" :title="step?.title || label || t('tourLabel','页面导览')" :close-label="t('close','关闭')" @update:model-value="emit('update:modelValue',$event)" @keydown="keyboard"><p v-if="step?.description" class="ui-tour__description">{{ step.description }}</p><p v-if="missing" class="ui-tour__missing" role="status">{{ t('tourMissing','此步骤目标暂不可用，仍可继续或关闭导览。') }}</p><p v-if="!steps.length">{{ t('empty','暂无内容') }}</p><template #footer><div class="ui-tour__footer"><span role="status" aria-live="polite" aria-atomic="true">{{ steps.length ? `${current+1} / ${steps.length}` : '0 / 0' }}</span><button v-if="steps.length" type="button" :disabled="current === 0" @click="select(current-1)">{{ t('previous','上一步') }}</button><button type="button" @click="current >= steps.length-1 ? finish() : select(current+1)">{{ current >= steps.length-1 ? t('tourFinish','完成导览') : t('next','下一步') }}</button></div></template></MDialog></span></template>
<style scoped>.ui-tour-host{display:contents}.ui-tour__dialog{position:fixed;inset:auto;margin:0;width:min(340px,calc(100% - 24px));max-width:calc(100% - 24px);max-height:calc(100dvh - 24px)}.ui-tour__dialog[open]{animation:ui-tour-appear 190ms ease-out}.ui-tour__dialog::backdrop{background:var(--ui-color-overlay);clip-path:var(--ui-tour-mask,none)}.ui-tour__description{margin:0;font:var(--ui-font-size-body)/1.8 var(--ui-font-family);overflow-wrap:anywhere}.ui-tour__missing{margin:12px 0 0;padding:10px;border-inline-start:2px solid var(--ui-color-warning);color:var(--ui-color-text-secondary);font-size:12px;line-height:1.7}.ui-tour__dialog :deep(.ui-dialog__header){padding:20px}.ui-tour__dialog :deep(.ui-dialog__body){padding:16px 20px}.ui-tour__dialog :deep(.ui-dialog__footer){padding:12px 16px}.ui-tour__footer{display:flex;align-items:center;justify-content:flex-end;flex-wrap:wrap;gap:10px;width:100%}.ui-tour__footer>span{margin-inline-end:auto;font:11px var(--ui-font-family-mono)}.ui-tour__footer button{min-height:44px;padding:8px 12px;border:1px solid var(--ui-color-border);background:var(--ui-color-surface);color:var(--ui-color-text);cursor:pointer}.ui-tour__footer button:last-child{border-color:var(--ui-color-accent);background:var(--ui-color-accent);color:var(--ui-color-on-accent)}.ui-tour__footer button:disabled{opacity:.4;cursor:not-allowed}.ui-tour__footer button:focus-visible{outline:2px solid var(--ui-color-focus);outline-offset:2px}@keyframes ui-tour-appear{from{opacity:0}to{opacity:1}}:global([data-ui-motion=reduced] .ui-tour__dialog[open]){animation:none}@media(prefers-reduced-motion:reduce){.ui-tour__dialog[open]{animation:none}}@media(forced-colors:active){.ui-tour__dialog::backdrop{background:Canvas;opacity:.6}.ui-tour__footer button{background:ButtonFace;color:ButtonText;border-color:ButtonText}}</style>
